using GameServer.Core.Protocol.Instance;
using GameServer.Core;

namespace GameServer.Modules.Deepwater;

/// <summary>The grid of an Allflame encounter area (the client's DeepwaterPlugin state, sent in 0x1d's extra data and
/// generated by the server the same way: Agents/docs/protocol/03-area-and-world.md §1, Agents/docs/re/011-level-generation.md
/// §3c4). A run started from the deck gets its chart's or board's grid (DeepwaterStart); any other new instance (a /goto)
/// gets a random one: a Chart run (DeepwaterEncounter) one room, a Voyage (DeepwaterEncounterVoyage) a 3 × 3 board, of the
/// ordinary rooms of the Sandy, Coral Forest and Coral Reef biomes.</summary>
internal static class DeepwaterGrid
{
    const string Plugin = "DeepwaterPlugin";
    const string VoyageArea = "DeepwaterEncounterVoyage";
    // Thermal Vents is not a chart biome; special rooms (Special) carry an encounter of their own, not built yet.
    static readonly string[] Biomes = ["Sandy", "CoralForest", "CoralReef"];

    /// <summary>The plugin's id in 0x1d's extra data (TerrainPlugins <c>__col1</c>).</summary>
    public static readonly Lazy<ushort?> PluginId = new(() => AreaTerrainPlugins.IdOf(Plugin));

    // The areas whose own terrain plugin is DeepwaterPlugin (the encounter areas, area type 52): Id → HASH16.
    static readonly Lazy<Dictionary<string, ushort>> Areas = new(() => ClientTables.TableOrEmpty("WorldAreas")
        .Select(a => (Id: a.Text("Id") ?? "", Hash: (ushort)a.Int("HASH16")))
        .Where(a => AreaTerrainPlugins.Of(a.Hash)?.Name == Plugin)
        .ToDictionary(a => a.Id, a => a.Hash));

    /// <summary>The area holds a DeepwaterPlugin (the client creates one there at every generation).</summary>
    public static bool IsEncounter(string areaId) => Areas.Value.ContainsKey(areaId);

    // The rooms a random grid takes: (DeepwaterRooms row, connection mask __col2, bits 1/2/4/8 = Left/Up/Right/Down).
    static readonly Lazy<(int Row, int Mask)[]> Rooms = new(() =>
    {
        var biomes = ClientTables.TableOrEmpty("DeepwaterBiomes").Where(b => Biomes.Contains(b.Text("Id"))).Select(b => (long)b.Index).ToHashSet();
        return [.. ClientTables.TableOrEmpty("DeepwaterRooms")
            .Where(r => r.LongOrNull("Biome") is { } b && biomes.Contains(b) && r.LongOrNull("Special") is null or 0 && r.Index <= byte.MaxValue)
            .Select(r => (r.Index, r.Int("__col2")))];
    });

    /// <summary>The state for a new instance of the area (null outside the encounter areas): u8 N, per cell (row-major,
    /// N·y + x) u8 DeepwaterRooms row, u8 orientation, u8 stat count (0), then u8 mod count (0). Cell N·y + x is at
    /// column x from the left and row y from the bottom of the board (<c>0x140420dc0</c>); cell 0, bottom-left, is the
    /// start, where the player arrives. Orientation o turns the room o quarter turns counter-clockwise
    /// (Right → Up).</summary>
    public static IReadOnlyList<(ushort Plugin, byte[] State)>? For(ushort areaHash)
    {
        if (PluginId.Value is not { } plugin || Areas.Value.FirstOrDefault(a => a.Value == areaHash).Key is not { } id || Rooms.Value.Length == 0)
            return null;
        int n = id == VoyageArea ? 3 : 1;
        var cells = Board(n, Random.Shared);
        var state = new List<byte> { (byte)n };
        foreach (var (row, turn) in cells) state.AddRange([(byte)row, (byte)turn, 0]);
        state.Add(0);
        return [(plugin, [.. state])];
    }

    /// <summary>The state of a run a chart or a board started (DeepwaterStart): the plan's rooms and rotations, per cell its
    /// stats (u32 Stats row + 1, u32 value; the planner's cell stats, at most 255), then the border modifiers in segment order
    /// (u16 Mods HASH16, a compact int per stat; none for a Chart or a 2 × 2 board). Generation reads only the rooms and
    /// rotations (DeepwaterGeneration.Parse).</summary>
    public static IReadOnlyList<(ushort Plugin, byte[] State)>? For(DeepwaterPlan plan)
    {
        if (PluginId.Value is not { } plugin) return null;
        var w = new BlobWriter().U8((byte)plan.Size);
        for (int i = 0; i < plan.Cells.Count; i++)
        {
            var chart = plan.Cells[i]?.Chart ?? default;
            var stats = plan.CellStats[i].Where(s => s.Value != 0).Take(255).ToList();
            w.U8(chart.Room).U8((byte)(chart.Rotation & 3)).U8((byte)stats.Count);
            foreach (var (key, value) in stats) w.U32(key).U32(unchecked((uint)value));
        }
        var border = plan.Border.Take(255).ToList();
        w.U8((byte)border.Count);
        foreach (var m in border)
        {
            w.U16(m.Hash);
            foreach (int v in m.Values) w.CompactI(v);
        }
        return [(plugin, w.ToArray())];
    }

    /// <summary>An encounter area as a map run opens it (WorldAreas HASH16, Id and name), or null.</summary>
    public static MapDevice.MapArea? AreaOf(string id) =>
        Areas.Value.TryGetValue(id, out ushort hash)
            ? new MapDevice.MapArea(hash, id, ClientTables.TableOrEmpty("WorldAreas").FirstOrDefault(a => a.Text("Id") == id) is { Table: not null } row ? row.Text("Name") ?? id : id, 0)
            : null;

    /// <summary>The client's turn of a room's mask by the cell's orientation (<c>0x141f34ee0</c>). Mask bits 1/2/4/8 are
    /// Left/Up/Right/Down (DeepwaterConnectionStrings): bit 4 opens to x + 1, bit 2 to y + 1, bit 1 to x − 1, bit 8 to
    /// y − 1; each turn moves Right → Up → Left → Down.</summary>
    static int Open(int mask, int turn) => ((mask << (4 - turn)) | (mask >> turn)) & 15;

    /// <summary>A random n × n board whose shared sides agree (both open or both closed; a side on the rim may be open)
    /// and whose every cell is reached from cell 0 (the bottom-left start). Without one after many tries, Cross
    /// rooms.</summary>
    static (int Row, int Turn)[] Board(int n, Random rng)
    {
        var rooms = Rooms.Value;
        for (int attempt = 0; attempt < 500; attempt++)
        {
            var cells = new (int Row, int Turn, int Open)[n * n];
            bool placed = true;
            for (int i = 0; i < n * n && placed; i++)
            {
                int x = i % n, y = i / n;
                var options = new List<(int, int, int)>();
                foreach (var (row, mask) in rooms)
                    for (int turn = 0; turn < 4; turn++)
                    {
                        int open = Open(mask, turn);
                        if (x > 0 && ((cells[i - 1].Open & 4) != 0) != ((open & 1) != 0)) continue;
                        if (y > 0 && ((cells[i - n].Open & 2) != 0) != ((open & 8) != 0)) continue;
                        options.Add((row, turn, open));
                    }
                if (options.Count == 0) placed = false;
                else cells[i] = options[rng.Next(options.Count)];
            }
            if (placed && Reached(cells.Select(c => c.Open).ToArray(), n) == n * n) return [.. cells.Select(c => (c.Row, c.Turn))];
        }
        var cross = rooms.Where(r => r.Mask == 15).ToArray();
        return [.. Enumerable.Range(0, n * n).Select(_ => (cross[rng.Next(cross.Length)].Row, rng.Next(4)))];
    }

    static int Reached(int[] open, int n)
    {
        var seen = new bool[open.Length];
        var todo = new Stack<int>([0]);
        seen[0] = true;
        int count = 1;
        while (todo.TryPop(out int i))
            foreach (var (bit, dx, dy) in new[] { (4, 1, 0), (1, -1, 0), (2, 0, 1), (8, 0, -1) })
            {
                int x = i % n + dx, y = i / n + dy;
                if ((open[i] & bit) == 0 || x < 0 || y < 0 || x >= n || y >= n || seen[y * n + x]) continue;
                seen[y * n + x] = true;
                count++;
                todo.Push(y * n + x);
            }
        return count;
    }
}
